@click.option("--all-methods", is_flag=True, help="Show HEAD and OPTIONS methods.")
@click.option("--domain", "-d", type=str, help="Filter routes by domain.")
@with_appcontext
def routes_command(sort: str, all_methods: bool, domain: str | None) -> None:
    """Show all registered routes with endpoints and methods."""

    rules = list(current_app.url_map.iter_rules())
    if not rules:
        click.echo("No routes were registered.")
        return

    ignored_methods = set(() if all_methods else ("HEAD", "OPTIONS"))

    host_matching = current_app.url_map.host_matching

    def get_domain(rule: Rule) -> str:
        if host_matching:
            return rule.host

        result = []

        if rule.subdomain:
            result.append(rule.subdomain)

        server_name = current_app.config["SERVER_NAME"]

        if server_name is not None:
            this_host = server_name
        else:
            this_host = ""

        result.append(this_host)
        result = [x for x in result if x is not None]
        return ".".join(result)

    if domain is not None:
        rules = [rule for rule in rules if domain == get_domain(rule)]

    if sort in ("endpoint", "rule"):
        rules = sorted(rules, key=attrgetter(sort))
    elif sort == "methods":
        rules = sorted(rules, key=lambda rule: sorted(rule.methods))  # type: ignore

    filtered_rules = sorted(rules, key=lambda rule: get_domain(rule))

    rule_methods = [
        ", ".join(sorted(rule.methods - ignored_methods))  # type: ignore
        for rule in filtered_rules
    ]

    headers = ("Domain", "Endpoint", "Methods", "Rule")
    widths = (
        max(len(get_domain(rule)) for rule in filtered_rules),
        max(len(rule.endpoint) for rule in filtered_rules),
        max(len(methods) for methods in rule_methods),
        max(len(rule.rule) for rule in filtered_rules),
    )
    widths = [max(len(h), w) for h, w in zip(headers, widths)]
    row = "{{0:<{0}}}  {{1:<{1}}}  {{2:<{2}}}  {{3:<{3}}}".format(*widths)

    click.echo(row.format(*headers).strip())
    click.echo(row.format(*("-" * width for width in widths)))

    for rule, methods in zip(filtered_rules, rule_methods):
        click.echo(
            row.format(
                get_domain(rule), rule.endpoint, methods, rule.rule
            ).rstrip()
        )


